const input = $input.first().json || {};
const required = ['tenantId','providerPhoneNumberId','senderId','providerMessageId'];
const missing = required.filter((k) => input[k] === undefined || input[k] === null || input[k] === '');
if (missing.length) throw new Error(`CASE002_APPOINTMENT_AGENT_INPUT_MISSING ${missing.join(',')}`);

const text = String(input.text || '').trim();
if (!text) return [];

const tenantId = String(input.tenantId);
const providerPhoneNumberId = String(input.providerPhoneNumberId);
const senderId = String(input.senderId).replace(/[^0-9]/g, '');
const providerMessageId = String(input.providerMessageId);
const traceId = String(input.providerEventId || providerMessageId);
const now = new Date();
const timezone = 'America/Lima';

const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};
store.appointments = store.appointments || {};
store.processedMessages = store.processedMessages || {};

if (store.processedMessages[providerMessageId]) return [];

const sessionKey = `${tenantId}:${senderId}`;
let session = store.sessions[sessionKey] || { step: 'idle' };
const lower = text.toLocaleLowerCase('es-PE');

function trimProcessed() {
  const entries = Object.entries(store.processedMessages);
  if (entries.length <= 500) return;
  entries.sort((a, b) => Number(a[1]) - Number(b[1]));
  for (const [key] of entries.slice(0, entries.length - 500)) delete store.processedMessages[key];
}

function response(body) {
  store.processedMessages[providerMessageId] = Date.now();
  trimProcessed();
  return [{
    json: {
      tenantId,
      providerPhoneNumberId,
      to: senderId,
      text: body,
      traceId,
      businessActionId: `case002-appointment-agent:${providerMessageId}`,
      idempotencyKey: `case002-appointment-agent:${providerPhoneNumberId}:${providerMessageId}`
    }
  }];
}

function activeAppointments() {
  return Object.values(store.appointments).filter((a) =>
    a && a.tenantId === tenantId && a.senderId === senderId && a.status === 'booked'
  );
}

function ymdInLima(date) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit'
  }).formatToParts(date);
  const map = Object.fromEntries(parts.map((p) => [p.type, p.value]));
  return `${map.year}-${map.month}-${map.day}`;
}

function weekdayInLima(date) {
  return new Intl.DateTimeFormat('en-US', { timeZone: timezone, weekday: 'short' }).format(date);
}

function slotLabel(iso) {
  const label = new Intl.DateTimeFormat('es-PE', {
    timeZone: timezone,
    weekday: 'long',
    day: '2-digit',
    month: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  }).format(new Date(iso));
  return label.replace(',', ' a las');
}

function availableSlots(limit = 4) {
  const slots = [];
  const occupied = new Set(
    Object.values(store.appointments)
      .filter((a) => a && a.tenantId === tenantId && a.status === 'booked')
      .map((a) => a.startsAt)
  );
  for (let dayOffset = 1; dayOffset <= 14 && slots.length < limit; dayOffset++) {
    const cursor = new Date(now.getTime() + dayOffset * 86400000);
    const weekday = weekdayInLima(cursor);
    if (weekday === 'Sat' || weekday === 'Sun') continue;
    const ymd = ymdInLima(cursor);
    for (const hour of ['09:00','11:00','14:00','16:00']) {
      const startsAt = `${ymd}T${hour}:00-05:00`;
      if (!occupied.has(startsAt)) slots.push(startsAt);
      if (slots.length >= limit) break;
    }
  }
  return slots;
}

if (/\b(reiniciar|empezar de nuevo|reset)\b/i.test(lower)) {
  store.sessions[sessionKey] = { step: 'idle' };
  return response('Listo. Empecemos de nuevo. ¿Qué servicio o revisión necesitas para tu vehículo?');
}

if (/\b(varad[oa]|gr[uú]a|no prende|inmovilizad[oa]|auxilio)\b/i.test(lower)) {
  store.sessions[sessionKey] = { step: 'human_review', reason: 'urgent_assistance', updatedAt: now.toISOString() };
  return response('Por lo que indicas, esto requiere atención humana/auxilio y no una cita automática. He dejado el caso marcado para revisión. No voy a asumir un diagnóstico ni que el vehículo sea seguro para conducir.');
}

if (/\b(garant[ií]a|repararon|misma falla|mismo ruido|volvi[oó] a fallar|comeback)\b/i.test(lower)) {
  store.sessions[sessionKey] = { step: 'human_review', reason: 'warranty_or_comeback', updatedAt: now.toISOString() };
  return response('Este caso parece relacionado con un trabajo previo o garantía. Lo correcto en el piloto es revisión humana del historial antes de crear una cita automática.');
}

if (/\b(mis citas|mi cita|ver cita)\b/i.test(lower)) {
  const active = activeAppointments();
  if (!active.length) return response('No tengo una cita activa registrada en este piloto para este número.');
  const lines = active.slice(-3).map((a, i) => `${i + 1}. ${slotLabel(a.startsAt)} — ${a.serviceSummary}${a.plate ? ` — placa ${a.plate}` : ''}`);
  return response(`Tus citas activas del piloto:\n${lines.join('\n')}\n\nPuedes escribir CANCELAR CITA si deseas anular la más reciente.`);
}

if (/\b(cancelar cita|anular cita|cancelar mi cita)\b/i.test(lower)) {
  const active = activeAppointments().sort((a, b) => String(a.createdAt).localeCompare(String(b.createdAt)));
  if (!active.length) return response('No encuentro una cita activa para cancelar en este piloto.');
  const appointment = active[active.length - 1];
  appointment.status = 'cancelled';
  appointment.cancelledAt = now.toISOString();
  session = { step: 'idle', lastAppointmentId: appointment.id };
  store.sessions[sessionKey] = session;
  return response(`Cita del piloto cancelada: ${slotLabel(appointment.startsAt)}. Si deseas otra, dime qué servicio necesitas.`);
}

if (session.step === 'human_review') {
  return response('Tu conversación está marcada para revisión humana. Si quieres iniciar un caso nuevo y no relacionado, escribe REINICIAR.');
}

if (session.step === 'idle') {
  const bookingIntent = /\b(cita|agend|reserv|taller|mec[aá]nic|mantenimiento|revisi[oó]n|freno|aceite|check engine|vibr|ruido|fuga)\b/i.test(lower);
  if (bookingIntent) {
    session = {
      step: 'awaiting_plate',
      serviceSummary: text,
      startedAt: now.toISOString(),
      updatedAt: now.toISOString()
    };
    store.sessions[sessionKey] = session;
    return response('Claro. Voy a preparar una cita de taller. ¿Cuál es la placa del vehículo? Puedes escribirla como ABC-123. Si no la tienes a mano, escribe NO TENGO.');
  }
  session = { step: 'awaiting_service', startedAt: now.toISOString(), updatedAt: now.toISOString() };
  store.sessions[sessionKey] = session;
  return response('Hola. Soy el asistente de recepción del taller. Puedo ayudarte a preparar una cita para mecánica sin hacer diagnósticos. ¿Qué servicio, mantenimiento o revisión necesitas?');
}

if (session.step === 'awaiting_service') {
  session.serviceSummary = text;
  session.step = 'awaiting_plate';
  session.updatedAt = now.toISOString();
  store.sessions[sessionKey] = session;
  return response('Entendido. ¿Cuál es la placa del vehículo? Puedes escribirla como ABC-123. Si no la tienes a mano, escribe NO TENGO.');
}

if (session.step === 'awaiting_plate') {
  const noPlate = /\b(no tengo|sin placa|no la tengo)\b/i.test(lower);
  const compact = text.toUpperCase().replace(/[^A-Z0-9]/g, '');
  const plateOk = /^[A-Z0-9]{6}$/.test(compact);
  if (!noPlate && !plateOk) {
    return response('No pude reconocer la placa. Envíala en un formato como ABC-123, o escribe NO TENGO para continuar.');
  }
  session.plate = noPlate ? null : `${compact.slice(0,3)}-${compact.slice(3)}`;
  const slots = availableSlots(4);
  if (!slots.length) {
    session.step = 'human_review';
    session.reason = 'no_test_slots';
    store.sessions[sessionKey] = session;
    return response('No encuentro horarios disponibles en el calendario de prueba. Dejo el caso para revisión humana.');
  }
  session.offeredSlots = slots;
  session.step = 'awaiting_slot';
  session.updatedAt = now.toISOString();
  store.sessions[sessionKey] = session;
  const choices = slots.map((slot, i) => `${i + 1}) ${slotLabel(slot)}`).join('\n');
  return response(`Tengo estos horarios disponibles:\n\n${choices}\n\nResponde solo con 1, 2, 3 o 4 para elegir.`);
}

if (session.step === 'awaiting_slot') {
  const match = lower.match(/^\s*([1-4])\s*$/);
  if (!match) {
    const choices = (session.offeredSlots || []).map((slot, i) => `${i + 1}) ${slotLabel(slot)}`).join('\n');
    return response(`Elige uno de los horarios respondiendo solo con 1, 2, 3 o 4:\n\n${choices}`);
  }
  const chosen = (session.offeredSlots || [])[Number(match[1]) - 1];
  if (!chosen) throw new Error('CASE002_APPOINTMENT_SLOT_SELECTION_INVALID');

  const alreadyTaken = Object.values(store.appointments).some((a) =>
    a && a.tenantId === tenantId && a.status === 'booked' && a.startsAt === chosen
  );
  if (alreadyTaken) {
    const slots = availableSlots(4);
    session.offeredSlots = slots;
    session.updatedAt = now.toISOString();
    store.sessions[sessionKey] = session;
    const choices = slots.map((slot, i) => `${i + 1}) ${slotLabel(slot)}`).join('\n');
    return response(`Ese horario acaba de ocuparse. Estas son las opciones actualizadas:\n\n${choices}\n\nResponde con 1, 2, 3 o 4.`);
  }

  const appointmentId = `case002_apt_${Date.now()}_${senderId.slice(-4)}`;
  const appointment = {
    id: appointmentId,
    tenantId,
    senderId,
    serviceSummary: String(session.serviceSummary || 'revisión de taller'),
    plate: session.plate || null,
    provider: 'case002-level2-internal',
    providerEventId: `sandbox:${appointmentId}`,
    startsAt: chosen,
    endsAt: new Date(new Date(chosen).getTime() + 60 * 60 * 1000).toISOString(),
    timezone,
    status: 'booked',
    sourceMessageId: providerMessageId,
    createdAt: now.toISOString()
  };
  store.appointments[appointmentId] = appointment;
  session.step = 'booked';
  session.lastAppointmentId = appointmentId;
  session.updatedAt = now.toISOString();
  store.sessions[sessionKey] = session;

  return response(`Cita reservada en el piloto: ${slotLabel(chosen)}. Motivo: ${appointment.serviceSummary}${appointment.plate ? `. Placa: ${appointment.plate}` : ''}.\n\nImportante: esta reserva queda persistida en el calendario interno Level-2 del piloto; todavía no es un evento de Google Calendar. Puedes escribir MIS CITAS o CANCELAR CITA.`);
}

if (session.step === 'booked') {
  const appointment = session.lastAppointmentId ? store.appointments[session.lastAppointmentId] : null;
  if (appointment && appointment.status === 'booked') {
    return response(`Tu cita del piloto sigue reservada para ${slotLabel(appointment.startsAt)}. Puedes escribir MIS CITAS, CANCELAR CITA o REINICIAR para iniciar otro caso.`);
  }
  store.sessions[sessionKey] = { step: 'idle' };
  return response('No encuentro una cita activa. ¿Qué servicio o revisión necesitas?');
}

throw new Error(`CASE002_APPOINTMENT_AGENT_UNKNOWN_STATE ${session.step}`);

const result = $input.first().json || {};
if (result.status !== 'accepted_by_provider') throw new Error('CASE002_APPOINTMENT_REPLY_NOT_ACCEPTED');
if (!result.providerMessageId) throw new Error('CASE002_APPOINTMENT_REPLY_PROVIDER_MESSAGE_ID_MISSING');
return [{ json: {
  ok: true,
  status: result.status,
  providerMessageId: String(result.providerMessageId),
  businessActionId: String(result.businessActionId || '')
} }];
